  run,
  strategy,
}: {
  run: number;
  strategy: Strategy;
}) {
  const signals = useContext(StageSignalContext);
  useEffect(() => {
    signals?.onSettled(run, strategy);
  }, [run, signals, strategy]);
  return null;
}
