// biome-ignore lint/performance/noNamespaceImport: Sentry SDK requires namespace import for proper initialization
import * as Sentry from "@sentry/nextjs";

// Send console.log, console.error, and console.warn calls as logs to Sentry
export const consoleLogging = () =>
  Sentry.consoleLoggingIntegration({ levels: ["log", "error", "warn"] });

export const baseOptions = (): Sentry.BrowserOptions => ({
  // Setting this option to true will print useful information to the console while you're setting up Sentry.
  debug: false,

  // Read directly rather than through `keys()`: Next inlines NEXT_PUBLIC_*
  // at build time, and `keys()` would bundle zod into the browser just to
  // re-check a constant. Apps validate it server-side via their env.ts.
  dsn: process.env.NEXT_PUBLIC_SENTRY_DSN,

  // Enable logging
  enableLogs: true,

  integrations: [consoleLogging()],

  // Adjust this value in production, or use tracesSampler for greater control
  tracesSampleRate: 1,
});

/**
 * Hands a caught render error to Sentry, loading the SDK only when there is a
 * DSN to report to. The error boundaries are part of every page's initial
 * bundle, so a static `@sentry/nextjs` import there shipped the SDK's core to
 * every visitor even with Sentry switched off. Next inlines `NEXT_PUBLIC_*` at
 * build time, which turns the check into a constant and drops the import.
 */
export const reportRenderError = (error: Error) => {
  if (!process.env.NEXT_PUBLIC_SENTRY_DSN) {
    return;
  }

  import("@sentry/nextjs").then(({ captureException }) =>
    captureException(error)
  );
};

