 */
let initialized = false;

/** Idempotent, so an error boundary can call it before the deferred start. */
export const initializeSentryWithoutReplay = (): void => {
  if (initialized) {
    return;
  }
  initialized = true;
  Sentry.init(baseOptions());
};

