async () => {
  await new Promise(r => setTimeout(r, 5000));
  const nav = performance.getEntriesByType('navigation')[0];
  const s = window.__SENTRY__;
  const ver = s && Object.keys(s).find(k => /^\d/.test(k));
  const client = ver && s[ver]?.defaultCurrentScope?._client;
  const integ = client?._options?.integrations?.map(i => i.name) ?? client && Object.keys(client._integrations || {});
  const late = performance.getEntriesByType('resource').filter(e => /chunks/.test(e.name) && e.startTime > nav.loadEventEnd).map(e => ({ n: e.name.split('/').pop(), start: Math.round(e.startTime), kb: Math.round(e.encodedBodySize/1024) }));
  return { load: Math.round(nav.loadEventEnd), sentryVersion: ver, integrations: integ, replay: integ?.includes?.('Replay'), afterLoadChunks: late };
}

